internal sealed record NativeBattleComponentSelector(ushort Effect, string TestClass, string TestMethod, string EnvironmentPrefix, string SourceFactory, string SourceArguments, bool SupportsQueuedSourceHandoff)
{
    internal string MethodFilter => "*" + TestClass + "." + TestMethod;
}

internal sealed record NativeBattleComponentSelectorEntry(ushort Effect, NativeBattleComponentSelector[] ExistingSelectors, string QueuedSourceTestClass, string QueuedSourceTestMethod, string QueuedSourceEnvironmentPrefix)
{
    internal bool HasExistingSourceHandoff => ExistingSelectors.Any(selector => selector.SupportsQueuedSourceHandoff);
    internal bool RequiresExternalPreparedSource => !HasExistingSourceHandoff;
}

